38	// blinkRouter builds a router whose view on screen wants a blink, with the
39	// clock stubbed at `at`. It returns the view and the recorded intervals.
40	func blinkRouter(t *testing.T, wants bool) (*App, *blinkView, *[]time.Duration) {
41		t.Helper()
42		got := stubAnimationEvery(t, time.UnixMilli(1000))
43		v := &blinkView{wants: wants}
44		a := router(t, v)
45		a.anim.blinkOn = true
46		return a, v, got
47	}
48	
49	func startBlinkChain(t *testing.T, a *App) {
50		t.Helper()
51		if a.ensureTick() == nil {
52			t.Fatal("a view that wants to blink got no animation chain")
53		}
54	}
55	
56	func tickAt(a *App, ms int64) tea.Cmd {
57		_, cmd := a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(ms)})
58		return cmd
59	}
60	
61	func lastFrame(t *testing.T, v *blinkView) jobs.FrameMsg {
62		t.Helper()
63		frames := framesSeen(&v.fakeView)
64		if len(frames) == 0 {
65			t.Fatal("the view was never handed a FrameMsg")
66		}
67		return frames[len(frames)-1]
68	}
