116	// Criterion 2: a row is never left on the "off" glyph.
117	func TestAStoppedChainLeavesThePhaseOn(t *testing.T) {
118		a, v, _ := blinkRouter(t, true)
119		startBlinkChain(t, a)
120		tickAt(a, 1500)
121		if lastFrame(t, v).Blink {
122			t.Fatal("setup: the tick at 1500 ms should be an off phase")
123		}
124	
125		v.wants = false
126		cmd := tickAt(a, 2500) // would be off again
127	
128		if !lastFrame(t, v).Blink || !a.anim.blinkOn {
129			t.Error("the chain died on an off phase; want a last FrameMsg{Blink: true}")
130		}
131		if _, ok := testutil.MsgOf[animationTickMsg](cmd); ok {
132			t.Error("the chain renewed itself after the view stopped blinking")
133		}
134	}
