136	// Criterion 3: work started after the chain died restarts it exactly once.
137	func TestAnOperationStartedAfterTheChainDiedRestartsItOnce(t *testing.T) {
138		got := stubAnimationEvery(t, time.UnixMilli(1000))
139		a := router(t, &blinkView{})
140	
141		a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
142		if len(*got) != 1 || (*got)[0] != animationFastInterval {
143			t.Fatalf("intervals after a start = %v, want one of %v", *got, animationFastInterval)
144		}
145		a.Update(testutil.Key("down"))
146		if len(*got) != 1 {
147			t.Errorf("a later Update asked for another chain: %v", *got)
148		}
149	}
150	
151	// Criterion 3: a faster need replaces the slower chain; the old one is dropped.
152	func TestAFasterNeedReplacesTheSlowerChain(t *testing.T) {
153		a, v, got := blinkRouter(t, true)
154		startBlinkChain(t, a)
155		old := a.anim.seq
156		if a.anim.interval != animationBlinkInterval {
157			t.Fatalf("blink chain interval = %v, want %v", a.anim.interval, animationBlinkInterval)
158		}
159	
160		a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
161	
162		if a.anim.seq != old+1 {
163			t.Errorf("seq = %d, want %d (a new chain)", a.anim.seq, old+1)
164		}
165		if last := (*got)[len(*got)-1]; last != animationFastInterval {
166			t.Errorf("replacement interval = %v, want %v", last, animationFastInterval)
167		}
168		frames := len(framesSeen(&v.fakeView))
169		_, cmd := a.Update(animationTickMsg{seq: old, at: time.UnixMilli(1000)})
170		if cmd != nil || len(framesSeen(&v.fakeView)) != frames {
171			t.Error("a tick of the replaced chain was not dropped silently")
172		}
173		cmd = tickAt(a, 1000)
174		if m, ok := testutil.MsgOf[animationTickMsg](cmd); !ok || m.seq != old+1 {
175			t.Error("the new chain was not renewed")
176		}
177	}
178	
179	// Criterion 7: the cadence follows the registry.
180	func TestTheCadenceFollowsTheRegistry(t *testing.T) {
181		a, _, got := blinkRouter(t, true)
182		startBlinkChain(t, a)
183		if (*got)[len(*got)-1] != animationBlinkInterval {
184			t.Fatalf("blink only: intervals %v, want %v", *got, animationBlinkInterval)
185		}
186	
187		id := a.jobs.Start(scanRun("default", "a"))
188		a.jobsChanged()
189		if (*got)[len(*got)-1] != animationFastInterval {
190			t.Fatalf("run started: intervals %v, want %v", *got, animationFastInterval)
191		}
192	
193		seq := a.anim.seq
194		a.jobs.Advance(id, "a", jobs.ItemDone, "")
195		cmd := tickAt(a, 1000)
196		if m, ok := testutil.MsgOf[animationTickMsg](cmd); !ok || m.seq != seq {
197			t.Errorf("run done, view still blinking: want the same chain renewed, got %v %v", m, ok)
198		}
199		if last := (*got)[len(*got)-1]; last != animationBlinkInterval {
200			t.Errorf("renewal interval = %v, want %v", last, animationBlinkInterval)
201		}
202	}
203	
204	// Criterion 7: the spinner frame moves only while work runs.
205	func TestTheFrameOnlyMovesWhileWorkRuns(t *testing.T) {
206		a, _, _ := blinkRouter(t, true)
207		startBlinkChain(t, a)
208		before := a.animationFrame()
209		for ms := int64(1000); ms <= 3000; ms += 500 {
210			tickAt(a, ms)
211		}
212		if a.animationFrame() != before {
213			t.Error("blink-only ticks advanced the spinner frame")
214		}
215	}
