217	// Criterion 5: static motion pins the phase on and starts no chain for pastilles.
218	func TestStaticMotionNeverStartsAChainForIndicators(t *testing.T) {
219		a, _, got := blinkRouter(t, true)
220		a.anim.blinkOn = false
221	
222		a.setMotionStatic(true)
223	
224		if !a.anim.blinkOn {
225			t.Error("setMotionStatic(true) did not pin the phase on")
226		}
227		if a.ensureTick() != nil {
228			t.Error("static motion started a chain for a blink")
229		}
230		a.Update(testutil.Key("down"))
231		if len(*got) != 0 {
232			t.Errorf("static motion recorded intervals %v", *got)
233		}
234	}
