236	// Criterion 5: a running spinner still ticks at 100 ms, with the phase pinned on.
237	func TestStaticMotionPinsThePhaseOn(t *testing.T) {
238		a, v, got := blinkRouter(t, true)
239		a.setMotionStatic(true)
240		a.Update(jobs.StartMsg{Run: scanRun("default", "a")})
241		if len(*got) == 0 || (*got)[len(*got)-1] != animationFastInterval {
242			t.Fatalf("static motion with a run: intervals %v, want %v", *got, animationFastInterval)
243		}
244		for _, ms := range []int64{1500, 2500} {
245			tickAt(a, ms)
246			if !lastFrame(t, v).Blink {
247				t.Errorf("tick at %d ms: Blink = false under static motion", ms)
248			}
249		}
250	}
