252	// Criterion 6: the router asks the view after the very Update that changed it.
253	func TestTheRouterAsksTheViewOnScreenAfterEveryUpdate(t *testing.T) {
254		a, v, _ := blinkRouter(t, false)
255		v.onKeyWow = func(b *blinkView) { b.wants = true }
256	
257		_, cmd := a.Update(testutil.Key("down"))
258	
259		m, ok := testutil.MsgOf[animationTickMsg](cmd)
260		if !ok {
261			t.Fatal("the Update that made the view want a blink did not return the chain")
262		}
263		if m.seq != a.anim.seq || !a.anim.ticking {
264			t.Error("the chain is not the router's live one")
265		}
266		for _, msg := range v.received {
267			if _, ok := msg.(animationTickMsg); ok {
268				t.Error("the view was asked to send the tick itself")
269			}
270		}
271	}
272	
273	// Criterion 6: only the view on screen is asked.
274	func TestAViewOffScreenDoesNotKeepTheChainAlive(t *testing.T) {
275		got := stubAnimationEvery(t, time.UnixMilli(1000))
276		on := &blinkView{wants: true}
277		off := &blinkView{wants: true}
278		a := router(t, &fakeView{})
279		a.views[command.ViewWorkspaces] = off
280		a.anim.blinkOn = true
281	
282		if a.ensureTick() != nil {
283			t.Error("a view off screen started a chain")
284		}
285		a.Update(testutil.Key("down"))
286		if len(*got) != 0 {
287			t.Errorf("a view off screen recorded intervals %v", *got)
288		}
289	
290		// A chain kept by the view on screen dies when the user leaves it.
291		a.views[command.ViewDashboard] = on
292		startBlinkChain(t, a)
293		a.currentView = command.ViewDashboard
294		a.views[command.ViewDashboard] = &fakeView{}
295		cmd := tickAt(a, 1000)
296		if _, ok := testutil.MsgOf[animationTickMsg](cmd); ok || a.anim.ticking {
297			t.Error("the chain outlived the view that wanted it")
298		}
299	}
