301	// spinnerView mimics a view with a footer spinner: it owns a bubbles spinner
302	// chain and returns the next Tick for each of its own TickMsg.
303	type spinnerView struct {
304		blinkView
305		sp spinner.Model
306	}
307	
308	func (v *spinnerView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
309		switch msg := msg.(type) {
310		case spinner.TickMsg:
311			var cmd tea.Cmd
312			v.sp, cmd = v.sp.Update(msg)
313			return v, cmd
314		case tea.KeyMsg:
315			if v.onKeyWow != nil {
316				v.onKeyWow(&v.blinkView)
317			}
318			return v, v.sp.Tick
319		}
320		return v, nil
321	}
322	
323	// Risk: the wrapper must not eat or replace the view's own command, with or
324	// without a chain started in the same Update, and the spinner must go on.
325	func TestTheWrapperKeepsTheViewsOwnCommand(t *testing.T) {
326		for _, tc := range []struct {
327			name      string
328			startsRun bool
329		}{{"no chain started", false}, {"chain started in the same Update", true}} {
330			t.Run(tc.name, func(t *testing.T) {
331				stubAnimationEvery(t, time.UnixMilli(1000))
332				v := &spinnerView{sp: spinner.New(spinner.WithSpinner(spinner.Dot))}
333				if tc.startsRun {
334					v.onKeyWow = func(b *blinkView) { b.wants = true }
335				}
336				a := router(t, v)
337	
338				_, cmd := a.Update(testutil.Key("down"))
339				tick, ok := testutil.MsgOf[spinner.TickMsg](cmd)
340				if !ok {
341					t.Fatal("the router lost the view's spinner command")
342				}
343				if tc.startsRun {
344					if _, ok := testutil.MsgOf[animationTickMsg](cmd); !ok {
345						t.Fatal("the chain was not started alongside the spinner")
346					}
347				}
348				// The spinner's own chain goes on through the router.
349				_, next := a.Update(tick)
350				if _, ok := testutil.MsgOf[spinner.TickMsg](next); !ok {
351					t.Error("the footer spinner stopped after going through the router")
352				}
353			})
354		}
355	}
356	
357	// Risk: a dropped tick adds nothing, even with a chain alive.
358	func TestAStaleTickIsStillAnsweredWithNothing(t *testing.T) {
359		a, _, _ := blinkRouter(t, true)
360		startBlinkChain(t, a)
361	
362		_, cmd := a.Update(animationTickMsg{seq: a.anim.seq - 1, at: time.UnixMilli(1000)})
363	
364		if cmd != nil {
365			t.Error("the wrapper added a command to a dropped tick")
366		}
367	}
368	
369	// -race: Cmds run on their own goroutines. The chain and the view's Cmd are
370	// built by Update and executed concurrently; neither may read the router.
371	func TestTheCommandsOfAnUpdateCanRunConcurrently(t *testing.T) {
372		a, v, _ := blinkRouter(t, true)
373		v.cmd = func(tea.Msg) tea.Cmd { return func() tea.Msg { return spinner.TickMsg{} } }
374		// No chain is alive yet, so this one Update starts it AND returns the view's own
375		// Cmd: the two must come out as a batch.
376		_, cmd := a.Update(testutil.Key("down"))
377		if cmd == nil {
378			t.Fatal("no command to run")
379		}
380		msgs := make(chan tea.Msg, 8)
381		done := make(chan struct{})
382		failures := make(chan string, 1)
383		go func() {
384			defer close(done)
385			batch, ok := cmd().(tea.BatchMsg)
386			if !ok {
387				failures <- "the Update's command is not a BatchMsg: the chain and the view's Cmd are not concurrent"
388				return
389			}
390			finished := make(chan struct{}, len(batch))
391			for _, c := range batch {
392				go func() { defer func() { finished <- struct{}{} }(); msgs <- c() }()
393			}
394			for range batch {
395				<-finished
396			}
397		}()
398		// Meanwhile the router goes on mutating its own state in Update.
399		for i := 0; i < 20; i++ {
400			a.Update(animationTickMsg{seq: a.anim.seq, at: time.UnixMilli(int64(1000 + 500*i))})
401		}
402		<-done
403		select {
404		case msg := <-failures:
405			t.Fatal(msg)
406		default:
407		}
408	}
409	
410	// Review: leaving static motion on while a chain left the view on the off phase
411	// must hand the view on screen an "on" frame, since no tick will.
412	func TestStaticMotionHandsTheViewOnScreenAnOnFrame(t *testing.T) {
413		a, v, _ := blinkRouter(t, true)
414		startBlinkChain(t, a)
415		tickAt(a, 1500) // 1500/500 is odd: the off half
416		if lastFrame(t, v).Blink {
417			t.Fatal("setup: the tick at 1500 ms should be the off phase")
