15	// blinkView is a fakeView that implements BlinkingView. wants is the level the
16	// router reads after every Update; onKey may flip it from inside a key press.
17	type blinkView struct {
18		fakeView
19		wants    bool
20		onKeyWow func(*blinkView)
21		// cmd, when set, is returned by every Update (a view's own command).
22		cmd func(tea.Msg) tea.Cmd
23	}
24	
25	func (v *blinkView) WantsBlink() bool { return v.wants }
26	
27	func (v *blinkView) Update(msg tea.Msg) (tea.Model, tea.Cmd) {
28		if _, ok := msg.(tea.KeyMsg); ok && v.onKeyWow != nil {
29			v.onKeyWow(v)
30		}
31		v.received = append(v.received, msg)
32		if v.cmd != nil {
33			return v, v.cmd(msg)
34		}
35		return v, nil
36	}
37	
38	// blinkRouter builds a router whose view on screen wants a blink, with the
39	// clock stubbed at `at`. It returns the view and the recorded intervals.
40	func blinkRouter(t *testing.T, wants bool) (*App, *blinkView, *[]time.Duration) {
41		t.Helper()
42		got := stubAnimationEvery(t, time.UnixMilli(1000))
43		v := &blinkView{wants: wants}
44		a := router(t, v)
45		a.anim.blinkOn = true
46		return a, v, got
47	}
