70	// Criterion 1: every row reads the phase of the tick.
71	func TestEveryRowReadsThePhaseOfTheTick(t *testing.T) {
72		a, v, _ := blinkRouter(t, true)
73		other := &blinkView{wants: true}
74		a.views[command.ViewWorkspaces] = other
75		startBlinkChain(t, a)
76	
77		for _, tt := range []struct {
78			ms   int64
79			want bool
80		}{{1000, true}, {1500, false}, {2000, true}} {
81			tickAt(a, tt.ms)
82			if got := lastFrame(t, v).Blink; got != tt.want {
83				t.Errorf("tick at %d ms: Blink = %v, want %v", tt.ms, got, tt.want)
84			}
85		}
86		tickAt(a, 2500) // off
87		a.switchView(command.ViewWorkspaces)
88		if got := lastFrame(t, other).Blink; got != a.anim.blinkOn || got {
89			t.Errorf("entering view Blink = %v, want the router's phase (off)", got)
90		}
91	}
