93	// Criterion 2: the chain dies when nothing animates any more.
94	func TestTheChainDiesWhenNothingAnimates(t *testing.T) {
95		a, v, got := blinkRouter(t, true)
96		startBlinkChain(t, a)
97	
98		v.wants = false
99		cmd := tickAt(a, 1000)
100	
101		if _, ok := testutil.MsgOf[animationTickMsg](cmd); ok {
102			t.Error("the chain renewed itself with nothing to animate")
103		}
104		if a.anim.ticking {
105			t.Error("the router still believes a chain is alive")
106		}
